# The task involves grid analysis with 7s forming patterns
# Let me look for connected components and structure

# Check connectivity by looking at each 7 and its neighbors
def find_connected_components(grid, value=7):
    """Find connected components of a given value"""
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    visited = set()
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == value and (r, c) not in visited:
                component = []
                stack = [(r, c)]
                while stack:
                    curr_r, curr_c = stack.pop()
                    if (curr_r, curr_c) in visited:
                        continue
                    visited.add((curr_r, curr_c))
                    component.append((curr_r, curr_c))

                    # Check neighbors (4-connectivity)
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == value and (nr, nc) not in visited:
                                stack.append((nr, nc))
                components.append(component)

    return components

components = find_connected_components(grid)
print(f"Number of connected components: {len(components)}")
for i, comp in enumerate(components):
    print(f"Component {i}: {sorted(comp)}")

